else if (etherTokens[_sourceToken]) {

safeTransferFrom(_sourceToken, msg.sender, this, _amount);

if (isNewerConverter)
IEtherToken(_sourceToken).withdraw(_amount);
}

else {

if (isNewerConverter)
safeTransferFrom(_sourceToken, msg.sender, firstConverter, _amount);
else
safeTransferFrom(_sourceToken, msg.sender, this, _amount);
}
