stepData.beneficiary = _beneficiary;

else if (data[i + 1].isV28OrHigherConverter)
stepData.beneficiary = data[i + 1].converter;

else
stepData.beneficiary = this;
}
else {

stepData.beneficiary = this;
}
}

return data;
}

