require(targetToken == addressOf(BNT_TOKEN), "ERR_INVALID_TARGET_TOKEN");

uint256 amount = convertByPath(_path, _amount, _minReturn, this, _affiliateAccount, _affiliateFee);

ensureAllowance(targetToken, bancorX, amount);

