if (msg.value > 0) {

require(msg.value == _amount, "ERR_ETH_AMOUNT_MISMATCH");

if (!isNewerConverter)
IEtherToken(getConverterEtherTokenAddress(firstConverter)).deposit.value(msg.value)();
